// manifest.hpp — engine.json <-> arb_engine_desc (engine-spec.md §3.8).
//
// The manifest's "params" is a *snapshot* of arb_describe() so the library
// browser, the phone and the site can render an engine without loading its
// binary. It is the one duplication in the system, so it is generated by
// arb-manifest at build time and re-checked against the binary at load; a box
// whose snapshot has drifted is ENGINE BROKEN (§7.4), never quietly accepted.
//
// Host-side only: engines never include this.
#pragma once

#include <charconv>
#include <cmath>
#include <cstdlib>
#include <cstring>
#include <limits>
#include <string>
#include <vector>

#include <nlohmann/json.hpp>

#include <arbutus_engine.h>

namespace arb::manifest {

using json = nlohmann::json;

// Fixed char arrays in the ABI need not be terminated when full.
inline std::string fixed(const char* p, std::size_t n) {
    const void* z = std::memchr(p, 0, n);
    return std::string(p, z ? std::size_t(static_cast<const char*>(z) - p) : n);
}

// A float widened to double dumps as 0.009999999776482582, which is exact and
// unreadable. The shortest text that round-trips the *float* reads as 0.01 and
// comes back as the same float, so the snapshot stays byte-comparable and a
// person can still read it.
inline double nice(float v) {
    char buf[32];
    const auto [end, ec] = std::to_chars(buf, buf + sizeof buf, v);
    if (ec != std::errc{}) return double(v);
    *end = '\0';
    return std::strtod(buf, nullptr);
}

inline const char* type_name(arb_param_type t) {
    switch (t) {
    case ARB_PARAM_INTEGER: return "integer";
    case ARB_PARAM_ENUM:    return "enum";
    default:                return "continuous";
    }
}

inline const char* curve_name(arb_curve c) {
    return c == ARB_CURVE_LOG ? "log" : "lin";
}

inline json caps_json(uint32_t caps) {
    static const char* names[ARB_CAP_COUNT] = ARB_CAP_NAMES;
    json a = json::array();
    for (int i = 0; i < ARB_CAP_COUNT; ++i)
        if (caps & (1u << i)) a.push_back(names[i]);
    return a;
}

// The asset keys, in declaration order. Present even when empty so a reader
// never has to distinguish "no assets" from "an older manifest".
inline json assets_json(const arb_engine_desc& d) {
    json a = json::array();
    for (uint8_t i = 0; i < d.num_assets && i < ARB_MAX_ASSETS; ++i)
        a.push_back(fixed(d.asset_keys[i], sizeof d.asset_keys[i]));
    return a;
}

// Does this engine accept `key`? The host's §7.4 check, so a patch naming an
// unknown asset is refused before any file is opened.
inline bool declares_asset(const arb_engine_desc& d, const std::string& key) {
    for (uint8_t i = 0; i < d.num_assets && i < ARB_MAX_ASSETS; ++i)
        if (fixed(d.asset_keys[i], sizeof d.asset_keys[i]) == key) return true;
    return false;
}

// A modulator's outputs (modulation-spec §3.1), in declaration order. Present
// and empty for every other role, for the same reason as "assets".
inline json outputs_json(const arb_engine_desc& d) {
    json a = json::array();
    for (uint32_t i = 0; i < d.num_outputs && i < ARB_MAX_OUTPUTS; ++i)
        a.push_back(json{{"id",      fixed(d.outputs[i].id, sizeof d.outputs[i].id)},
                         {"name",    fixed(d.outputs[i].name, sizeof d.outputs[i].name)},
                         {"bipolar", d.outputs[i].bipolar != 0}});
    return a;
}

inline json param_json(const arb_param_desc& p) {
    json j{
        {"id",    fixed(p.id, sizeof p.id)},
        {"name",  fixed(p.name, sizeof p.name)},
        {"type",  type_name(p.type)},
        {"curve", curve_name(p.curve)},
        {"min",   nice(p.min)},
        {"max",   nice(p.max)},
        {"def",   nice(p.def)},
        {"step",  nice(p.step)},
        {"unit",  fixed(p.unit, sizeof p.unit)},
        // ABI 2 (§15.1). Written always, like honours_env, so a reader never
        // has to know which ABI produced the file to know what absence means.
        {"per_voice", p.per_voice != 0},
        {"per_note",  p.per_note != 0},
    };
    if (p.type == ARB_PARAM_ENUM && p.labels) {
        json l = json::array();
        const int n = int(p.max - p.min) + 1;
        for (int i = 0; i < n; ++i) l.push_back(p.labels[i] ? p.labels[i] : "");
        j["labels"] = l;
    }
    return j;
}

// Everything the binary is the authority on. Authored fields (author,
// description, ...) are merged over this by arb-manifest.
inline json from_desc(const arb_engine_desc& d, const std::string& arch,
                      const std::string& binary_rel) {
    json params = json::array();
    for (uint32_t i = 0; i < d.num_params; ++i) params.push_back(param_json(d.params[i]));

    json keys = json::array();
    for (uint32_t i = 0; i < d.num_softkeys; ++i)
        keys.push_back(json{{"id",    fixed(d.softkeys[i].id, sizeof d.softkeys[i].id)},
                            {"label", fixed(d.softkeys[i].label, sizeof d.softkeys[i].label)}});

    return json{
        {"format", 1},
        {"kind", "engine"},
        {"id", fixed(d.id, sizeof d.id)},
        {"version", fixed(d.version, sizeof d.version)},
        {"abi", d.abi},
        {"caps", caps_json(d.caps)},
        {"honours_env", d.honours_env != 0},
        {"latency_frames", d.latency_frames},
        {"arch", json{{arch, binary_rel}}},
        {"params", params},
        {"softkeys", keys},
        {"assets", assets_json(d)},
        {"outputs", outputs_json(d)},
    };
}

// `v` as a uint32_t when it is a whole number in range (1 and 1.0 both are),
// else false. A plain get<uint32_t>() truncates, so `"abi": 2.5` read as 2 and
// loaded (#786).
inline bool whole(const json& v, uint32_t& out) {
    double d;
    if (v.is_number_unsigned()) d = double(v.get<uint64_t>());
    else if (v.is_number_integer()) d = double(v.get<int64_t>());
    else if (v.is_number_float()) d = v.get<double>();
    else return false;
    if (!(d >= 0.0 && d <= 4294967295.0) || d != std::floor(d)) return false;   // NaN fails too
    out = uint32_t(d);
    return true;
}

namespace detail {
// A field present with the wrong type is a mismatch, never read as its default
// (#786: `"min": "0"` matched a min of 0). An absent field is its default, so a
// manifest that predates a field still validates. The NUL in the mismatch
// string cannot match: fixed() stops at the first one.
inline std::string get_str(const json& j, const char* key, const char* fallback = "") {
    auto it = j.find(key);
    if (it == j.end()) return std::string(fallback);
    return it->is_string() ? it->get<std::string>() : std::string(1, '\0');
}
// A wrongly typed flag is a mismatch, not an exception out of the loader.
inline int get_bool(const json& j, const char* key, bool fallback = false) {
    auto it = j.find(key);
    if (it == j.end()) return fallback ? 1 : 0;
    return it->is_boolean() ? (it->get<bool>() ? 1 : 0) : -1;
}
// NaN for a non-number: it equals no float, so the field mismatches.
inline float get_num(const json& j, const char* key, float fallback = 0.0f) {
    auto it = j.find(key);
    if (it == j.end()) return fallback;
    return it->is_number() ? it->get<float>() : std::numeric_limits<float>::quiet_NaN();
}
}  // namespace detail

// "" when the snapshot matches the binary, else the first difference found.
// Floats are compared exactly: both sides are the same float widened to double
// and back, so drift means an edit, not rounding.
inline std::string validate(const json& m, const arb_engine_desc& d) {
    using detail::get_bool;
    using detail::get_num;
    using detail::get_str;

    if (get_str(m, "kind") != "engine") return "manifest kind is not \"engine\"";
    uint32_t abi = 0, latency = 0;
    if (!m.contains("abi") || !whole(m["abi"], abi) || abi != d.abi)
        return "manifest abi != arb_describe()";
    if (get_str(m, "id") != fixed(d.id, sizeof d.id))
        return "manifest id \"" + get_str(m, "id") + "\" != \"" + fixed(d.id, sizeof d.id) + "\"";
    if (get_str(m, "version") != fixed(d.version, sizeof d.version))
        return "manifest version != arb_describe()";
    if (m.value("caps", json::array()) != caps_json(d.caps))
        return "manifest caps != arb_describe()";
    if (m.value("honours_env", false) != (d.honours_env != 0))
        return "manifest honours_env != arb_describe()";
    if (m.contains("latency_frames") ? !whole(m["latency_frames"], latency) || latency != d.latency_frames
                                     : d.latency_frames != 0)
        return "manifest latency_frames != arb_describe()";

    const json params = m.value("params", json::array());
    if (params.size() != d.num_params)
        return "manifest has " + std::to_string(params.size()) + " params, binary has " +
               std::to_string(d.num_params);
    for (uint32_t i = 0; i < d.num_params; ++i) {
        const json& p = params[i];
        const arb_param_desc& b = d.params[i];
        const std::string where = "param " + std::to_string(i) + " (" + fixed(b.id, sizeof b.id) + ")";
        if (get_str(p, "id") != fixed(b.id, sizeof b.id))       return where + ": id";
        if (get_str(p, "name") != fixed(b.name, sizeof b.name)) return where + ": name";
        if (get_str(p, "type", "continuous") != type_name(b.type))  return where + ": type";
        if (get_str(p, "curve", "lin") != curve_name(b.curve))      return where + ": curve";
        if (get_num(p, "min") != b.min)                             return where + ": min";
        if (get_num(p, "max") != b.max)                             return where + ": max";
        if (get_num(p, "def") != b.def)                             return where + ": def";
        if (get_num(p, "step") != b.step)                           return where + ": step";
        if (get_str(p, "unit") != fixed(b.unit, sizeof b.unit))     return where + ": unit";
        if (get_bool(p, "per_voice") != (b.per_voice ? 1 : 0))  return where + ": per_voice";
        if (get_bool(p, "per_note") != (b.per_note ? 1 : 0))    return where + ": per_note";
        if (p.contains("labels") != (b.type == ARB_PARAM_ENUM && b.labels != nullptr))
            return where + ": labels";
        if (p.contains("labels")) {
            const int n = int(b.max - b.min) + 1;
            if (int(p["labels"].size()) != n) return where + ": label count";
            for (int k = 0; k < n; ++k)
                if (p["labels"][std::size_t(k)].get<std::string>() != std::string(b.labels[k] ? b.labels[k] : ""))
                    return where + ": label " + std::to_string(k);
        }
    }

    if (m.value("assets", json::array()) != assets_json(d))
        return "manifest assets != arb_describe()";
    if (m.value("outputs", json::array()) != outputs_json(d))
        return "manifest outputs != arb_describe()";

    const json keys = m.value("softkeys", json::array());
    if (keys.size() != d.num_softkeys) return "manifest softkey count != arb_describe()";
    for (uint32_t i = 0; i < d.num_softkeys; ++i) {
        if (get_str(keys[i], "id") != fixed(d.softkeys[i].id, sizeof d.softkeys[i].id))
            return "softkey " + std::to_string(i) + ": id";
        if (get_str(keys[i], "label") != fixed(d.softkeys[i].label, sizeof d.softkeys[i].label))
            return "softkey " + std::to_string(i) + ": label";
    }
    return {};
}

}  // namespace arb::manifest
